public sealed class PrinterInvoiceWindow:Window
{
 readonly PrinterSettingsService service=new();readonly SaleHistoryRecord? sale;readonly IReadOnlyList<SaleHistoryItem> items;
 readonly ListView printers=new(){Height=170,MinWidth=250};readonly ComboBox headerSize=new(),totalSize=new(),margin=new();
 readonly TextBox preview=new(){IsReadOnly=true,FontFamily=new FontFamily("Consolas"),FontSize=12,TextWrapping=TextWrapping.NoWrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Auto,BorderThickness=new Thickness(0),Background=Brushes.White};
 readonly TextBlock status=new(){Foreground=Brushes.DimGray,TextWrapping=TextWrapping.Wrap};PrinterPreferences prefs=new();IReadOnlyList<PrinterQueueInfo> queues=[];
 public PrinterInvoiceWindow(SaleHistoryRecord? sale=null,IReadOnlyList<SaleHistoryItem>? items=null){this.sale=sale;this.items=items??Array.Empty<SaleHistoryItem>();Title="Printer & Invoice | F9 / Ctrl+P: Thermal Print";Width=1320;Height=820;MinWidth=980;MinHeight=650;WindowStartupLocation=WindowStartupLocation.CenterOwner;Background=Brushes.WhiteSmoke;Content=Layout();Loaded+=async(_,_)=>await LoadAsync();PreviewKeyDown+=async(_,e)=>{if(e.Key==System.Windows.Input.Key.F9||(e.Key==System.Windows.Input.Key.P&&System.Windows.Input.Keyboard.Modifiers==System.Windows.Input.ModifierKeys.Control)){e.Handled=true;await PrintReceiptAsync();}else if(e.Key==System.Windows.Input.Key.Escape){Close();e.Handled=true;}};}
 UIElement Layout(){var root=new DockPanel{Margin=new Thickness(20)};var header=new DockPanel{LastChildFill=false,Margin=new Thickness(0,0,0,14)};var back=Btn("← Back");back.Click+=(_,_)=>Close();DockPanel.SetDock(back,Dock.Left);header.Children.Add(back);var title=new TextBlock{Text="Printer & Invoice",FontSize=24,FontWeight=FontWeights.Bold,VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(14,0,0,0)};header.Children.Add(title);DockPanel.SetDock(header,Dock.Top);root.Children.Add(header);
 var split=new Grid();split.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(450),MinWidth=360});split.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(14)});split.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star),MinWidth=420});
 var left=new DockPanel{Margin=new Thickness(0,0,8,0)};var printerCard=Card();var p=new StackPanel();p.Children.Add(new TextBlock{Text="PRINTER",FontWeight=FontWeights.Bold,Foreground=Brushes.DimGray});var row=new DockPanel{Margin=new Thickness(0,8,0,8)};printers.View=CreatePrinterView();row.Children.Add(printers);var scan=Btn("Refresh");scan.Click+=async(_,_)=>await RefreshPrintersAsync();DockPanel.SetDock(scan,Dock.Right);row.Children.Add(scan);p.Children.Add(row);var select=Btn("Select as Preferred Printer");select.Click+=async(_,_)=>await SelectPrinterAsync();p.Children.Add(select);printerCard.Child=p;DockPanel.SetDock(printerCard,Dock.Top);left.Children.Add(printerCard);
 var config=Card();var cfg=new StackPanel();cfg.Children.Add(new TextBlock{Text="RECEIPT CONFIGURATION",FontWeight=FontWeights.Bold,Foreground=Brushes.DimGray,Margin=new Thickness(0,0,0,10)});cfg.Children.Add(new TextBlock{Text="Paper width"});cfg.Children.Add(new TextBlock{Text="80 mm (576 dots)",FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,4,0,10)});cfg.Children.Add(new TextBlock{Text="Header size"});headerSize.Items.Add("Small");headerSize.Items.Add("Normal");headerSize.Items.Add("Large");cfg.Children.Add(headerSize);cfg.Children.Add(new TextBlock{Text="Total size",Margin=new Thickness(0,10,0,4)});totalSize.Items.Add("Small");totalSize.Items.Add("Normal");totalSize.Items.Add("Large");cfg.Children.Add(totalSize);cfg.Children.Add(new TextBlock{Text="Margins (mm)",Margin=new Thickness(0,10,0,4)});for(int i=0;i<=4;i++)margin.Items.Add(i);cfg.Children.Add(margin);var saveCfg=Btn("Save Configuration");saveCfg.Click+=async(_,_)=>await SavePreferencesAsync();cfg.Children.Add(saveCfg);config.Child=cfg;DockPanel.SetDock(config,Dock.Top);left.Children.Add(config);
 var actions=Card();var actionPanel=new StackPanel();var print=Btn("Thermal Receipt");print.Background=new SolidColorBrush(Color.FromRgb(23,59,50));print.Foreground=Brushes.White;print.FontWeight=FontWeights.Bold;print.HorizontalContentAlignment=HorizontalAlignment.Center;print.Click+=async(_,_)=>await PrintReceiptAsync();actionPanel.Children.Add(print);var testPrint=Btn("Test Print");testPrint.Click+=async(_,_)=>await TestPrintAsync();actionPanel.Children.Add(testPrint);var previewBtn=Btn("Invoice Preview");previewBtn.Click+=(_,_)=>ShowInvoicePreview();actionPanel.Children.Add(previewBtn);var share=Btn("Share Bill (Copy Text)");share.Click+=(_,_)=>ShareBill();actionPanel.Children.Add(share);var sharePdf=Btn("Share PDF");sharePdf.Click+=async(_,_)=>await SavePdfAsync(true);actionPanel.Children.Add(sharePdf);var savePdf=Btn("Save PDF to Device");savePdf.Click+=async(_,_)=>await SavePdfAsync(false);actionPanel.Children.Add(savePdf);actions.Child=actionPanel;DockPanel.SetDock(actions,Dock.Top);left.Children.Add(actions);
 var right=new DockPanel{Margin=new Thickness(8,0,0,0)};var previewCard=Card();var pc=new DockPanel();var previewTitle=new TextBlock{Text="Receipt Preview",FontSize=17,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,0,0,10)};DockPanel.SetDock(previewTitle,Dock.Top);pc.Children.Add(previewTitle);pc.Children.Add(preview);previewCard.Child=pc;right.Children.Add(previewCard);DockPanel.SetDock(status,Dock.Bottom);status.Margin=new Thickness(0,10,0,0);right.Children.Add(status);Grid.SetColumn(right,2);split.Children.Add(right);Grid.SetColumn(left,0);split.Children.Add(left);root.Children.Add(split);
 headerSize.SelectionChanged+=(_,_)=>RefreshPreview();totalSize.SelectionChanged+=(_,_)=>RefreshPreview();margin.SelectionChanged+=(_,_)=>RefreshPreview();return root;}
 static Border Card()=>new(){Background=Brushes.White,BorderBrush=new SolidColorBrush(Color.FromRgb(220,229,224)),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(10),Padding=new Thickness(16),Margin=new Thickness(0,0,0,12)};
 static Button Btn(string s)=>new(){Content=s,Padding=new Thickness(12,9,12,9),Margin=new Thickness(0,0,0,8),Cursor=System.Windows.Input.Cursors.Hand};
 GridView CreatePrinterView(){var view=new GridView();var printerCell=new FrameworkElementFactory(typeof(StackPanel));printerCell.SetValue(StackPanel.OrientationProperty,Orientation.Horizontal);var icon=new FrameworkElementFactory(typeof(TextBlock));icon.SetValue(TextBlock.TextProperty,"▣");icon.SetValue(TextBlock.MarginProperty,new Thickness(0,0,8,0));var printerName=new FrameworkElementFactory(typeof(TextBlock));printerName.SetBinding(TextBlock.TextProperty,new Binding("Name"));printerCell.AppendChild(icon);printerCell.AppendChild(printerName);view.Columns.Add(new GridViewColumn{Header="Printer",CellTemplate=new DataTemplate{VisualTree=printerCell},Width=210});view.Columns.Add(new GridViewColumn{Header="Status",DisplayMemberBinding=new Binding("DisplayStatus"),Width=95});var button=new FrameworkElementFactory(typeof(Button));button.SetValue(Button.ContentProperty,"Connect");button.SetValue(Button.PaddingProperty,new Thickness(8,4,8,4));button.SetBinding(Button.TagProperty,new Binding());button.AddHandler(Button.ClickEvent,new RoutedEventHandler(async(sender,args)=>{if(sender is Button b&&b.Tag is PrinterQueueInfo q)await SelectPrinterAsync(q);}));view.Columns.Add(new GridViewColumn{Header="Action",CellTemplate=new DataTemplate{VisualTree=button},Width=85});return view;}

 async Task LoadAsync(){prefs=await service.LoadAsync();headerSize.SelectedIndex=Math.Clamp(prefs.HeaderSize-1,0,2);totalSize.SelectedIndex=Math.Clamp(prefs.TotalSize-1,0,2);margin.SelectedItem=prefs.MarginMm;await RefreshPrintersAsync();RefreshPreview();}
 async Task RefreshPrintersAsync(){try{queues=await service.GetInstalledAsync();printers.ItemsSource=queues;if(!string.IsNullOrWhiteSpace(prefs.PreferredPrinter)){var saved=queues.FirstOrDefault(x=>x.Name==prefs.PreferredPrinter);printers.SelectedItem=saved;status.Text=saved is null?"Saved printer is unavailable. Select another printer explicitly.":saved.IsAvailable?"Saved printer is available in Windows.":"Saved printer queue is offline or unavailable."; }else status.Text="Select a Windows printer queue."; }catch(Exception e){status.Text="Printer discovery failed: "+e.Message;}}
 async Task SelectPrinterAsync(PrinterQueueInfo? chosen=null){var q=chosen??printers.SelectedItem as PrinterQueueInfo;if(q is null){status.Text="Choose a printer from the list first.";return;}printers.SelectedItem=q;prefs=prefs with{PreferredPrinter=q.Name};await service.SaveAsync(prefs);status.Text=q.IsAvailable?$"Preferred printer saved: {q.Name} (Windows queue available).":$"Preferred printer saved: {q.Name}, but its queue is currently unavailable/offline.";}
 async Task SavePreferencesAsync(){prefs=prefs with{HeaderSize=headerSize.SelectedIndex+1,TotalSize=totalSize.SelectedIndex+1,MarginMm=margin.SelectedItem is int v?v:2,PaperWidthMm=80};await service.SaveAsync(prefs);RefreshPreview();status.Text="Printer configuration saved.";}
 void RefreshPreview(){if(!IsLoaded)return;prefs=prefs with{HeaderSize=Math.Max(1,headerSize.SelectedIndex+1),TotalSize=Math.Max(1,totalSize.SelectedIndex+1),MarginMm=margin.SelectedItem is int v?v:2};preview.Text=EscPosReceiptBuilder.BuildText(sale,items,prefs);}
 async Task PrintReceiptAsync(){if(sale is null){status.Text="No invoice selected. Open Printer & Invoice from a saved bill.";return;}if(printers.SelectedItem is not PrinterQueueInfo q){status.Text="Select a printer first.";return;}if(!q.IsAvailable){status.Text="Selected printer is offline/unavailable. Choose an available queue.";return;}try{prefs=prefs with{PreferredPrinter=q.Name,HeaderSize=Math.Max(1,headerSize.SelectedIndex+1),TotalSize=Math.Max(1,totalSize.SelectedIndex+1),MarginMm=margin.SelectedItem is int v?v:2};await service.SaveAsync(prefs);await service.PrintRawAsync(q.Name,EscPosReceiptBuilder.BuildBytes(preview.Text,prefs));status.Text="Receipt data sent to the selected Windows printer queue. Verify the physical print."; }catch(Exception e){status.Text="Thermal receipt print failed: "+e.Message;}}
 async Task TestPrintAsync(){if(printers.SelectedItem is not PrinterQueueInfo q){status.Text="Select a printer first.";return;}if(!q.IsAvailable){status.Text="Selected printer queue is unavailable.";return;}try{var p=prefs with{PreferredPrinter=q.Name,HeaderSize=Math.Max(1,headerSize.SelectedIndex+1),TotalSize=Math.Max(1,totalSize.SelectedIndex+1),MarginMm=margin.SelectedItem is int v?v:2};await service.SaveAsync(p);var sample="KHAN BABA GENERAL STORE\\nTHERMAL PRINTER TEST\\n80mm ESC/POS\\nPrinter queue: "+q.Name+"\\n\\nIf this prints correctly, receipt output is ready for hardware verification.\\n\\n";await service.PrintRawAsync(q.Name,EscPosReceiptBuilder.BuildBytes(sample,p));status.Text="Test print sent to the selected queue. Check paper alignment and cutter on the physical printer.";}catch(Exception e){status.Text="Test print failed: "+e.Message;}}
 void ShowInvoicePreview(){if(sale is null){MessageBox.Show("No saved invoice selected.","Invoice Preview");return;}if(sale.SaleId<=0){status.Text="Unposted draft receipt preview is shown in the preview pane.";return;}new SaleDetailsWindow(sale,items){Owner=this}.ShowDialog();}
 void ShareBill(){if(sale is null)return;Clipboard.SetText(preview.Text);status.Text="Bill text copied. Paste it into your preferred sharing app.";}
 async Task SavePdfAsync(bool openAfterSave){if(sale is null){status.Text="Open a saved invoice first to export PDF.";return;}var dialog=new SaveFileDialog{Filter="PDF document (*.pdf)|*.pdf",DefaultExt=".pdf",AddExtension=true,FileName=sale.SaleId<=0?"KhanBaba_Draft_Preview.pdf":$"KhanBaba_Invoice_{sale.SaleId:D6}.pdf",Title="Save Khan Baba Invoice"};if(dialog.ShowDialog(this)!=true)return;try{await File.WriteAllBytesAsync(dialog.FileName,PdfReceiptBuilder.Build(preview.Text));if(openAfterSave)Process.Start(new ProcessStartInfo(dialog.FileName){UseShellExecute=true});status.Text=openAfterSave?"PDF saved and opened. Attach it from your PDF viewer or file manager to share.":"PDF saved to "+dialog.FileName;}catch(Exception e){status.Text="PDF export failed: "+e.Message;}}

}